import { summonSanctifier, sanctifyStrict, sanctifyLoose, sanctifyKeyboardOnlyEmoji, sanctifyKeyboardOnly, sanctifyPasted, VERSION, inspectText, inspectTextDetailed, getNewlineStats, getRecommendedSanctifierOptions, revealInvisible } from '../dist/text-sanctifier.min.js';
import { readFileSync } from 'node:fs';
import assert from 'node:assert/strict';
import * as source from '../src/index.js';
import * as browser from '../dist/text-sanctifier.min.js';

// Compare every browser export against source on a shared corpus. Keep explicit
// expected-value tests below: parity alone cannot catch a bug shared by both builds.
assert.deepEqual(Object.keys(browser), Object.keys(source));
const corpus = [
  '', 'plain ASCII\t text\r\nnext\rline\n',
  '\uFEFFa\u00A0b\u202Fc\u3000d\u200B\u2060',
  '\u0000\u0007\u0085\u061C\u2066\u2069\u034F\u3164',
  '\u{E0041}\u{E007F}\u{E0100}\u{E0FFF}\u180B\uFE0F',
  '\u{1F469}\u{1F3FD}\u200D\u{1F4BB} 1\uFE0F\u20E3 \u{1F1E8}\u{1F1E6}',
  '\uDB40\u200B\uDC68\uD800x\uDC00',
];
const presets = ['sanctifyStrict', 'sanctifyLoose', 'sanctifyKeyboardOnly', 'sanctifyKeyboardOnlyEmoji', 'sanctifyPasted'];
for (const text of corpus) {
  for (const name of [...presets, 'inspectText', 'getNewlineStats', 'revealInvisible']) {
    assert.deepEqual(browser[name](text), source[name](text), name);
  }
  for (const maxFindings of [undefined, 0, 1, Infinity, -1, 0.5, NaN, null]) {
    assert.deepEqual(browser.inspectTextDetailed(text, { maxFindings }), source.inspectTextDetailed(text, { maxFindings }));
  }
  assert.deepEqual(browser.getRecommendedSanctifierOptions(browser.inspectText(text)), source.getRecommendedSanctifierOptions(source.inspectText(text)));
  for (const options of [
    {}, { normalizeSpaces: true }, { purgeZeroWidthSpaces: true },
    { purgeInvisibleChars: true }, { nukeControls: true }, { purgeEmojis: true },
    { keyboardOnlyFilter: true }, { normalizeNewlines: true },
    { trimSpacesAroundNewlines: true }, { collapseNewLines: true },
    { collapseNewLines: true, preserveParagraphs: true },
    { collapseSpaces: true }, { finalTrim: true },
    { maxLength: 1, onMaxLength: 'truncate' }, { maxLength: 0, onMaxLength: 'noop' },
  ]) assert.equal(browser.summonSanctifier(options)(text), source.summonSanctifier(options)(text));
}
for (const name of [...presets, 'inspectText', 'inspectTextDetailed', 'getNewlineStats', 'revealInvisible']) {
  for (const value of [null, undefined, 42, {}, ['text']]) assert.throws(() => browser[name](value), TypeError, name);
}
assert.throws(() => browser.summonSanctifier({ maxLength: 1 })('ab'), RangeError);
assert.equal(browser.summonSanctifier({ maxLength: 1, onMaxLength: 'truncate' })('\u{1F600}'), '');
assert.equal(browser.summonSanctifier({ trimSpacesAroundNewlines: true })('a \r\n b'), 'a\nb');
assert.equal(browser.summonSanctifier({ collapseNewLines: true })('a\r\r\nb'), 'a\nb');
assert.equal(browser.sanctifyStrict('a\u00A0b\u3000c'), 'a b\u3000c');
assert.equal(browser.revealInvisible('\u2764\uFE0F'), '\u2764<U+FE0F>');

{
  const cp = String.fromCodePoint;
  const purge = summonSanctifier({ purgeEmojis: true });
  for (const emoji of [cp(0x1F44D, 0x1F3FD), cp(0x1F468, 0x200D, 0x1F469, 0x200D, 0x1F467), cp(0x1F469, 0x1F3FD, 0x200D, 0x1F4BB), cp(0x1F1E8, 0x1F1E6), '1' + cp(0xFE0F, 0x20E3), cp(0x2764, 0xFE0F)]) {
    assertEqual(purge('a' + emoji + 'b'), 'ab', 'dist purges complete emoji');
    assertEqual(sanctifyKeyboardOnlyEmoji(emoji), emoji, 'dist keeps complete emoji');
    assertEqual(inspectText(emoji).hasNonKeyboardChars, false, 'dist emoji is keyboard safe');
  }
  assertEqual(purge(cp(0x1F600, 0x200D) + 'hello world'), cp(0x200D) + 'hello world', 'dist keeps word after ZWJ');
  assertEqual(purge(cp(0xA9, 0x2122)), cp(0xA9, 0x2122), 'dist keeps plain pictographs');
  assertEqual(purge(cp(0xA9, 0xFE0F)), '', 'dist purges emoji copyright');
}


// We'll create multiple sanitizers to simulate the options
const strictSanctify = summonSanctifier.strict;
const looseSanctify = summonSanctifier.loose;

const customSanctify = summonSanctifier({
  purgeInvisibleChars: true,
  normalizeNewlines: true,
  collapseNewLines: true,
  collapseSpaces: true,
  trimSpacesAroundNewlines: true,
  nukeControls: true,
  finalTrim: true,
});

const aggressiveSanctifier = summonSanctifier({
  purgeInvisibleChars: true,
  preserveParagraphs: false,
  normalizeNewlines: true,
  collapseNewLines: true,
  collapseSpaces: true,
  nukeControls: true,
  trimSpacesAroundNewlines: true,
  finalTrim: true,
});


function assertEqual(actual, expected, message) {
  if (actual !== expected) {
    console.error(`❌ ${message}\n  Expected: "${expected}"\n  Received: "${actual}"`);
    process.exitCode = 1;
  } else {
    console.log(`✅ ${message}`);
  }
}

console.log('Running text-sanctifier dist tests...');

// 1. Basic invisible character purge
assertEqual(
  customSanctify('Hello\u200BWorld'),
  'HelloWorld',
  '1. Purge zero-width space'
);

// 2. Normalize CRLF line endings
assertEqual(
  customSanctify('Line1\r\nLine2\rLine3'),
  'Line1\nLine2\nLine3',
  '2. Normalize line endings to Unix \\n'
);

// 3. Collapse multiple spaces (using strict)
assertEqual(
  strictSanctify('Hello   World'),
  'Hello World',
  '3. Collapse multiple spaces into one (strict)'
);

// 4. Collapse multiple newlines (loose)
assertEqual(
  looseSanctify('Line1\n\n\nLine2'),
  'Line1\n\nLine2',
  '4. Preserve paragraph breaks (2 newlines) (loose)'
);

// 5. Summoned sanitizer (aggressive)
assertEqual(
  aggressiveSanctifier('A\t\n\n\u0008B'),
  'A\nB',
  '5. Aggressively nuke control chars and collapse newlines'
);

// 6. Trim spaces around newlines
assertEqual(
  customSanctify('Line1   \n   Line2'),
  'Line1\nLine2',
  '6. Trim spaces around newlines'
);

// 7. Preserve tabs even when collapsing spaces
assertEqual(
  strictSanctify('Hello\t\tWorld'),
  'Hello\t\tWorld',
  '7. Preserve tabs even in strict mode'
);

// 8. Purge mixed Unicode junk
assertEqual(
  customSanctify('\u200B\u200C\u200D Hello\u200F\u202DWorld\u202E'),
  'HelloWorld',
  '8. Purge diverse invisible Unicode trash'
);

// 9. Collapse 6+ newlines into paragraph break
assertEqual(
  looseSanctify('A\n\n\n\n\n\nB'),
  'A\n\nB',
  '9. Collapse 6+ newlines into \\n\\n paragraph'
);

// 10. No collapse when paragraph preservation off
assertEqual(
  strictSanctify('X\n\nY'),
  'X\nY',
  '10. Collapse double newline to single (strict)'
);

// 11. Fully purge ghost characters
const ghostInput = 'A\u200B\u200C\u200D\u2060\uFEFF\u200E\u200F\u202A\u202E\u00A0B';
assertEqual(
  customSanctify(ghostInput),
  'AB',
  '11. Ghostproof: Fully purge invisible Unicode'
);







// 12. Keyboard-onlyEmoji: preserve ASCII + emojis, strip non-keyboard extras
const keyboardEmojiSanctifier = summonSanctifier.keyboardOnlyEmoji;

assertEqual(
  keyboardEmojiSanctifier('Hello — World 😊 👽 𝌆 ‼\uFE0F'),
  'Hello - World 😊 👽  ‼\uFE0F',
  '12. keyboardOnlyEmoji: normalize dashes and preserve emojis'
);

// 13. Keyboard-onlyEmoji: normalize smart quotes and dashes
assertEqual(
  keyboardEmojiSanctifier(`“Hello”—‘World’`),
  '"Hello"-\'World\'',
  '13. keyboardOnlyEmoji: normalize smart quotes and dashes'
);

// 14. Keyboard-only strict: purge emojis and normalize symbols
const keyboardStrict = summonSanctifier.keyboardOnly;

assertEqual(
  keyboardStrict('Hi 😊 — “there”! 👋'),
  'Hi - "there"!',
  '14. keyboardOnly: emojis removed, symbols normalized, spaces collapsed'
);

// 15. Keyboard-onlyEmoji: normalize full-width ASCII punctuation
assertEqual(
  keyboardEmojiSanctifier('Ｈｅｌｌｏ！Ｗｏｒｌｄ？'),
  'Hello!World?',
  '15. keyboardOnlyEmoji: full-width punctuation normalized'
);








// 16. Bidi isolates and the Arabic letter mark are purged by the dist build
{
  const input = 'A' + [0x061C, 0x2066, 0x2067, 0x2068, 0x2069].map(cp => String.fromCharCode(cp)).join('') + 'B';
  assertEqual(customSanctify(input), 'AB', '16. Purge bidi isolates and ALM');
}

// 17. The dist build keeps the public property names
{
  const report = inspectText('A' + String.fromCharCode(0x2066) + 'B');
  assertEqual(report.hasControlChars, true, '17. inspectText.hasControlChars survives minification');
  assertEqual(getRecommendedSanctifierOptions(report).nukeControls, true, '17. getRecommendedSanctifierOptions survives minification');

  const detailed = inspectTextDetailed(String.fromCharCode(0xFEFF) + 'x' + String.fromCharCode(0x2067), { maxFindings: 1 });
  const f = detailed.findings[0];
  assertEqual(
    JSON.stringify([f.offset, f.line, f.column, f.codePoint, f.category, f.atStart]),
    JSON.stringify([0, 1, 1, 0xFEFF, 'bom', true]),
    '17. inspectTextDetailed finding fields survive minification'
  );
  assertEqual(
    JSON.stringify([detailed.counts.bom, detailed.counts.bidi_control, detailed.total, detailed.truncated]),
    JSON.stringify([1, 1, 2, true]),
    '17. inspectTextDetailed counts/total/truncated and maxFindings survive minification'
  );
}

// 17b. getNewlineStats is exported by the dist build and keeps its field names
{
  const stats = getNewlineStats('a' + String.fromCharCode(13, 10) + 'b' + String.fromCharCode(13) + 'c' + String.fromCharCode(10));
  assertEqual(
    JSON.stringify([stats.crlf, stats.cr, stats.lf, stats.types, stats.mixed]),
    JSON.stringify([1, 1, 1, ['CRLF', 'CR', 'LF'], true]),
    '17b. getNewlineStats fields survive minification'
  );
}

// 18. Astral trash (tag characters) is located and purged by the dist build, and the new counts survive
{
  const tags = [0xE0048, 0xE0069].map(cp => String.fromCodePoint(cp)).join('');
  const detailed = inspectTextDetailed('a' + tags + String.fromCharCode(0x3164));
  assertEqual(
    JSON.stringify(detailed.findings.map(f => [f.offset, f.column, f.codePoint, f.category])),
    JSON.stringify([[1, 2, 0xE0048, 'tag'], [3, 4, 0xE0069, 'tag'], [5, 6, 0x3164, 'hangul_filler']]),
    '18. astral findings survive minification'
  );
  assertEqual(
    JSON.stringify([detailed.counts.tag, detailed.counts.hangul_filler, detailed.counts.variation_selector, detailed.counts.invisible_format]),
    JSON.stringify([2, 1, 0, 0]),
    '18. new count fields survive minification'
  );
  assertEqual(customSanctify('A' + tags + 'B'), 'AB', '18. tag characters purged by the dist build');
}

// 18b. Default-ignorables in other planes (1BCxx, 1D1xx, the end of plane 14) and Mongolian FVS
{
  const hidden = [0x1BCA0, 0x1D173, 0xE0FFF, 0x180B].map(cp => String.fromCodePoint(cp)).join('');
  const detailed = inspectTextDetailed('x' + hidden + '\u{1F600}y');
  assertEqual(
    JSON.stringify(detailed.findings.map(f => [f.codePoint, f.category])),
    JSON.stringify([[0x1BCA0, 'invisible_format'], [0x1D173, 'invisible_format'], [0xE0FFF, 'invisible_format'], [0x180B, 'variation_selector']]),
    '18b. default-ignorables in other planes are located; an emoji is not'
  );
  assertEqual(customSanctify('A' + hidden + 'B'), 'AB', '18b. default-ignorables in other planes purged by the dist build');
}


// 19. Options and exports added in 1.3.5 work in the dist build
{
  const c = (cp) => String.fromCodePoint(cp);
  assertEqual(summonSanctifier({ maxLength: 3, onMaxLength: 'truncate' })('abcdef'), 'abc', '19. onMaxLength survives minification');
  assertEqual(
    summonSanctifier.pasted('a' + c(0xA0) + 'b' + c(0x200B) + c(0x0D) + c(0x0A) + c(0x1F468) + c(0x200D) + c(0x1F469)),
    'a b' + c(0x0A) + c(0x1F468) + c(0x200D) + c(0x1F469),
    '19. pasted preset in the dist build'
  );
  assertEqual(summonSanctifier({ normalizeSpaces: true, purgeInvisibleChars: true })('a' + c(0xA0) + 'b'), 'a b', '19. normalizeSpaces survives minification');
  assertEqual(summonSanctifier({ purgeZeroWidthSpaces: true })('a' + c(0x200B) + 'b' + c(0x200D)), 'ab' + c(0x200D), '19. purgeZeroWidthSpaces survives minification');
  assertEqual(revealInvisible('x' + c(0x200B) + 'y' + c(0xE0041)), 'x<U+200B>y<U+E0041>', '19. revealInvisible exported by the dist build');
  assertEqual(revealInvisible('x' + c(0x202E), { format: (cp, cat) => '[' + cat + ']' }), 'x[bidi_control]', '19. revealInvisible format option survives minification');
}


// 20. Standalone preset exports in the dist build
{
  assertEqual(summonSanctifier.strict === sanctifyStrict, true, '20. summonSanctifier.strict is sanctifyStrict');
  assertEqual(summonSanctifier.loose === sanctifyLoose, true, '20. summonSanctifier.loose is sanctifyLoose');
  assertEqual(summonSanctifier.keyboardOnlyEmoji === sanctifyKeyboardOnlyEmoji, true, '20. summonSanctifier.keyboardOnlyEmoji is sanctifyKeyboardOnlyEmoji');
  assertEqual(summonSanctifier.keyboardOnly === sanctifyKeyboardOnly, true, '20. summonSanctifier.keyboardOnly is sanctifyKeyboardOnly');
  assertEqual(summonSanctifier.pasted === sanctifyPasted, true, '20. summonSanctifier.pasted is sanctifyPasted');
}


// 21. VERSION in the dist build equals package.json
{
  const pkg = JSON.parse(readFileSync(new URL('../package.json', import.meta.url), 'utf8'));
  assertEqual(VERSION, pkg.version, '21. VERSION exported by the dist build');
}


// 22. The dist build keeps split surrogate halves apart and does not recommend deleting content
{
  const split = String.fromCharCode(0xDB40, 0x200B, 0xDC68);
  assertEqual(inspectTextDetailed(sanctifyStrict(split)).counts.tag, 0, '22. no tag characters created');
  assertEqual(getRecommendedSanctifierOptions(inspectText('caf' + String.fromCharCode(0xE9))).keyboardOnlyFilter, false, '22. keyboardOnlyFilter stays opt-in');
}


console.log('All dist tests finished.');
